import { notFound } from "next/navigation";
import Link from "next/link";
import { createSupabaseServerClient } from "../../../lib/supabase/server";
import { decodeDisplayText } from "../../../lib/text";
import FavoriteButton from "../../../components/FavoriteButton";
import AnalyticsEvent from "../../../components/AnalyticsEvent";
import VendorTierBadge from "../../../components/VendorTierBadge";
import VendorContactLink from "../../../components/VendorContactLink";
import { createAdminClient } from "../../../lib/supabase/admin";
import { vendorDescription, socialImage } from "../../../lib/seo";


export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const db=createAdminClient();const {data:v}=await db.from("vendor_profiles").select("business_name,description,city,state,primary_category,pricing_from,status").eq("slug",slug).eq("market_slug","portland").maybeSingle();if(!v||v.status!=="active")return {title:"Wedding Vendor"};const description=vendorDescription(v);return {title:`${v.business_name} | Portland Wedding Vendor`,description,alternates:{canonical:`/vendor/${slug}`},openGraph:{title:v.business_name,description,url:`/vendor/${slug}`,type:"website",images:[socialImage]},twitter:{card:"summary_large_image",title:v.business_name,description,images:[socialImage.url]}}}
function photoUrl(path:string){return `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/vendor-media/${path}`}
function safeHref(value:string){return value.startsWith("http")?value:`https://${value}`}
function videoEmbed(value:string){
  try{
    const u=new URL(safeHref(value.trim()));
    const host=u.hostname.toLowerCase().replace(/^www\./,"");
    let id="";
    if(host==="youtu.be") id=u.pathname.split("/").filter(Boolean)[0]||"";
    else if(host.endsWith("youtube.com")){
      if(u.pathname==="/watch") id=u.searchParams.get("v")||"";
      else {
        const parts=u.pathname.split("/").filter(Boolean);
        if(["embed","shorts","live"].includes(parts[0]||"")) id=parts[1]||"";
      }
    }
    if(id){
      const start=u.searchParams.get("t")||u.searchParams.get("start")||"";
      const seconds=/^\d+$/.test(start)?start:(()=>{const m=start.match(/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/);return m?String((Number(m[1]||0)*3600)+(Number(m[2]||0)*60)+Number(m[3]||0)):""})();
      return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}${seconds?`?start=${seconds}`:""}`;
    }
    if(host.endsWith("vimeo.com")){const vimeoId=u.pathname.split("/").filter(Boolean).findLast(x=>/^\d+$/.test(x)); return vimeoId?`https://player.vimeo.com/video/${vimeoId}`:"";}
  }catch{}
  return "";
}

export default async function VendorProfile({params,searchParams}:{params:Promise<{slug:string}>,searchParams:Promise<{lead?:string,review?:string,from?:string}>}){
 const {slug}=await params; const q=await searchParams; const supabase=await createSupabaseServerClient(); const {data:{user}}=await supabase.auth.getUser();
 const {data:v}=await supabase.from("vendor_profiles").select("id,slug,business_name,listing_state,primary_category,description,email,phone,website,instagram,facebook,tiktok,pinterest,youtube,video_urls,city,state,service_radius,service_cities,pricing_from,pricing_typical,pricing_packages,wedding_styles,availability_status,unavailable_dates,vendor_attributes,guest_capacity_min,guest_capacity_max,plan,status,founding_vendor,founding_vendor_position,rating,review_count,vendor_photos(id,storage_path,alt_text,sort_order),reviews(id,rating,title,body,status,created_at)").eq("market_slug","portland").eq("slug",slug).maybeSingle();
 if(!v) notFound(); const fromBuilder=q.from==="wedding-builder"; await supabase.from("analytics_events").insert(fromBuilder?[{market_slug:"portland",vendor_id:v.id,event_type:"profile_view"},{market_slug:"portland",vendor_id:v.id,event_type:"builder_profile_view"}]:[{market_slug:"portland",vendor_id:v.id,event_type:"profile_view"}]);
 let initialFavorite=false; if(user){const {data:f}=await supabase.from("favorites").select("vendor_id").eq("user_id",user.id).eq("vendor_id",v.id).maybeSingle();initialFavorite=!!f;}
 const plan=v.plan||"free"; const unclaimed=(v as any).listing_state==="unclaimed"; const paid=plan!=="free" && !unclaimed; const pro=plan==="professional"||plan==="premium"; const premium=plan==="premium";
 const photos=((v as any).vendor_photos||[]).sort((a:any,b:any)=>(a.sort_order||0)-(b.sort_order||0)); const reviews=((v as any).reviews||[]); const hero=photos[0];
 const social=[['Instagram',v.instagram],['Facebook',v.facebook],['TikTok',v.tiktok],['Pinterest',v.pinterest],['YouTube',v.youtube]].filter(([,url])=>url);
 const videos=(v.video_urls||[]).map((url:string)=>({url,embed:videoEmbed(url)})).filter((x:{url:string,embed:string})=>Boolean(x.embed)).slice(0,3);
 const jsonLd={"@context":"https://schema.org","@type":"LocalBusiness","name":decodeDisplayText(v.business_name),"description":decodeDisplayText(v.description||""),"url":v.website||undefined,"telephone":v.phone||undefined,"email":v.email||undefined,"address":{"@type":"PostalAddress","addressLocality":v.city||"Portland","addressRegion":v.state||"OR","addressCountry":"US"},...(v.rating&&v.review_count?{"aggregateRating":{"@type":"AggregateRating","ratingValue":Number(v.rating),"reviewCount":Number(v.review_count)}}:{})};
 return <main className="vendorProfilePage"><script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify(jsonLd).replace(/</g,"\\u003c")}}/><AnalyticsEvent name="Vendor Profile Viewed" properties={{vendor_slug:slug,founding_vendor:!!v.founding_vendor,plan}}/>
  <section className={`vendorProfileHero compact ${hero?"hasImage":""}`} style={hero?{backgroundImage:`linear-gradient(90deg,rgba(24,32,27,.78),rgba(24,32,27,.28)),url(${photoUrl(hero.storage_path)})`}:{}}><div className="container vendorProfileHeroInner"><div className="vendorHeroCopy"><VendorTierBadge plan={plan} foundingVendor={v.founding_vendor}/><div className="vendorBreadcrumbs"><span>Vendors</span><span>›</span><span>{decodeDisplayText(v.city||"Portland")}, {v.state||"OR"}</span></div><h1>{decodeDisplayText(v.business_name)}</h1><div className="vendorHeroMeta"><span>📍 {decodeDisplayText(v.city||"Portland")}, {v.state||"OR"}</span><span>♡ {decodeDisplayText(v.primary_category||"Wedding Vendor")}</span>{v.rating?<span>★ {v.rating}{v.review_count?` · ${v.review_count} reviews`:""}</span>:null}</div></div><div className="heroActions"><FavoriteButton vendorId={v.id} initialFavorite={initialFavorite} loggedIn={!!user} source={fromBuilder?"wedding_builder":"profile"}/></div></div></section>
  <section className="vendorProfileBody section"><div className="container vendorProfileLayout"><div className="vendorProfileMain">
    {photos.length>1&&<div className="vendorProfilePhotoRibbon" aria-label={`${decodeDisplayText(v.business_name)} portfolio preview`}>{photos.slice(1,premium?5:pro?4:3).map((p:any,i:number)=><figure className={`vendorRibbonPhoto ribbon${i+1}`} key={p.id}><img src={photoUrl(p.storage_path)} alt={decodeDisplayText(p.alt_text||v.business_name)}/></figure>)}</div>}
    <nav className="vendorProfileTabs" aria-label="Vendor profile sections"><a href="#about">About</a>{paid&&<a href="#services">Services</a>}{paid&&photos.length>1&&<a href="#gallery">Gallery</a>}{paid&&<a href="#reviews">Reviews</a>}{premium&&videos.length>0&&<a href="#video">Video</a>}</nav>
    <div className="vendorStoryBlock" id="about"><span className="eyebrow">Meet the vendor</span><div className="storyHeading"><h2>About {decodeDisplayText(v.business_name)}</h2></div><p>{decodeDisplayText(v.description||"This business has a basic My Portland Wedding listing. Upgrade information is available from the vendor directly.")}</p></div>
    {paid&&<div className="vendorHighlights" id="services">{v.pricing_from&&<div><span>Starting at</span><strong>${Number(v.pricing_from).toLocaleString()}</strong></div>}{v.pricing_typical&&<div><span>Typical booking</span><strong>${Number(v.pricing_typical).toLocaleString()}</strong></div>}<div><span>Service area</span><strong>{v.service_radius?`${v.service_radius} miles from Portland`:(v.service_cities?.slice(0,3).join(" · ")||"Portland metro")}</strong></div>{v.wedding_styles?.length?<div><span>Style</span><strong>{v.wedding_styles.slice(0,2).join(" · ")}</strong></div>:null}</div>}
    {paid&&Array.isArray(v.pricing_packages)&&v.pricing_packages.length>0&&<section className="profileFeatureSection" id="packages"><div className="profileSectionHeading"><div><span className="eyebrow">Packages</span><h2>Ways to work together</h2></div></div><div className="packageGrid">{v.pricing_packages.map((pkg:any,i:number)=><article className="packageCard" key={`${pkg.name}-${i}`}><div>{pkg.popular&&<span className="badge mpwVendorBadge">Most Popular</span>}<h3>{decodeDisplayText(pkg.name||"Wedding Package")}</h3><strong>{pkg.price?`$${Number(pkg.price).toLocaleString()}`:"Contact for pricing"}</strong></div>{pkg.description&&<p>{decodeDisplayText(pkg.description)}</p>}{Array.isArray(pkg.includes)&&pkg.includes.length>0&&<ul>{pkg.includes.map((x:string)=><li key={x}>✓ {decodeDisplayText(x)}</li>)}</ul>}</article>)}</div></section>}{paid&&<section className="profileFeatureSection availabilityStrip"><span className="eyebrow">Availability</span><h2>{v.availability_status==="limited"?"Limited dates remaining":v.availability_status==="booked"?"Currently fully booked":"Currently accepting weddings"}</h2><p className="meta">Wedding Builder checks vendor-provided availability when a couple includes a wedding date.</p></section>}{premium&&videos.length>0&&<section className="profileFeatureSection" id="video"><div className="profileSectionHeading"><div><span className="eyebrow">Featured video</span><h2>See their work in motion</h2></div></div><div className="vendorVideoGrid">{videos.map(({url,embed}:{url:string,embed:string})=><div className="videoFrame" key={url}><iframe src={embed} title={`${v.business_name} video`} loading="lazy" referrerPolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen/></div>)}</div></section>}
    {paid&&photos.length>1&&<section className="profileFeatureSection" id="gallery"><div className="profileSectionHeading"><div><span className="eyebrow">Portfolio</span><h2>A closer look</h2></div></div><div className="vendorGalleryExpanded">{photos.slice(1,premium?20:pro?10:5).map((p:any)=><img key={p.id} src={photoUrl(p.storage_path)} alt={decodeDisplayText(p.alt_text||v.business_name)}/>)}</div></section>}
    {pro&&social.length>0&&<section className="profileFeatureSection socialShowcase"><div><span className="eyebrow">Follow along</span><h2>Find {decodeDisplayText(v.business_name)} on social</h2></div><div className="socialPills">{social.map(([name,url])=><VendorContactLink key={name as string} vendorId={v.id} kind="social" platform={String(name).toLowerCase()} source={fromBuilder?"wedding_builder":"profile"} href={safeHref(String(url))} target="_blank" rel="noreferrer">{name as string} ↗</VendorContactLink>)}</div></section>}
    {paid&&<section className="profileFeatureSection" id="reviews"><div className="profileSectionHeading"><div><span className="eyebrow">Kind words</span><h2>Reviews from couples</h2></div>{user&&<a href="#leave-review" className="textLink">Leave a review ↓</a>}</div>{reviews.length>0?reviews.map((r:any)=><div className="review" key={r.id}><strong>{"★".repeat(Number(r.rating))} {decodeDisplayText(r.title||"")}</strong>{r.status!=="approved"&&<span className="pendingReview">Pending approval</span>}<p>{decodeDisplayText(r.body||"")}</p></div>):<div className="emptyReviews"><span>♡</span><p>No approved reviews yet.</p></div>}<div className="leaveReview" id="leave-review"><span className="eyebrow">Share your experience</span><h3>Worked with {decodeDisplayText(v.business_name)}?</h3>{q.review==="submitted"&&<div className="notice success">Thank you! Your review was submitted and is awaiting approval.</div>}{q.review==="preview"&&<div className="notice success">Preview mode: review submission was simulated. No live review was created.</div>}{user?<form action="/api/reviews" method="post" className="reviewForm"><input type="hidden" name="vendor_id" value={v.id}/><input type="hidden" name="vendor_slug" value={slug}/><input type="hidden" name="source" value={fromBuilder?"wedding_builder":"profile"}/><label>Rating<select name="rating" defaultValue="5"><option value="5">5 — Amazing</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Fair</option><option value="1">1 — Poor</option></select></label><label>Review title<input name="title" placeholder="A quick headline"/></label><label>Your review<textarea name="body" rows={4} required/></label><button className="btn primary">Submit Review</button></form>:<div className="reviewLogin"><p>Sign in with a free couple account to leave a review.</p><Link className="btn light" href={`/couple/login?message=${encodeURIComponent("Sign in to leave a review")}`}>Couple Sign In</Link></div>}</div></section>}
  </div><aside className="vendorProfileSidebar">
    {unclaimed?<div className="profileContactCard claimBusinessCard"><span className="eyebrow">Business owner?</span><h3>Claim this business</h3><p>This complimentary listing has not yet been claimed or verified by the business. Claim it to control your profile and contact information.</p><Link className="btn primary" href={`/claim-business?vendor=${encodeURIComponent(slug)}`}>Claim This Business →</Link></div>:paid?<div className="profileContactCard" id="contact"><span className="eyebrow">Start a conversation</span><h3>Contact {decodeDisplayText(v.business_name)}</h3>{q.lead==="sent"&&<div className="notice success">Your inquiry was sent.</div>}{q.lead==="preview"&&<div className="notice success">Preview mode: inquiry submission was simulated. No live vendor lead or notification was created.</div>}{q.lead==="error"&&<div className="notice error">We could not send your inquiry. Please try again.</div>}{q.lead==="vendor-not-found"&&<div className="notice error">This vendor is not currently available for direct inquiries.</div>}{q.lead==="upgrade-required"&&<div className="notice error">Direct inquiries are not available for this listing.</div>}<form action="/api/leads" method="post"><input type="hidden" name="vendor_slug" value={slug}/><input type="hidden" name="source" value={fromBuilder?"wedding_builder":"profile"}/><input name="name" placeholder="Your name" required/><input name="email" type="email" placeholder="Your email" required/><input name="wedding_date" type="date"/><textarea name="message" rows={4} required placeholder="Tell them a little about your wedding…"/><button className="btn primary">Send Message →</button></form><small>🔒 Your information is kept private.</small></div>:<div className="profileContactCard freeListingCard"><span className="eyebrow">Free listing</span><h3>Basic business information</h3><p>This vendor has a limited free profile. Direct inquiries and Wedding Builder by My Portland Wedding matching are available to paid members.</p></div>}
    <div className="profileDetailsCard"><h3>Vendor details</h3><p>📍 {decodeDisplayText(v.city||"Portland")}, {v.state||"OR"}</p>{unclaimed?<p className="meta">Contact details hidden until this business is claimed.</p>:<>{v.phone&&<VendorContactLink vendorId={v.id} kind="phone" source={fromBuilder?"wedding_builder":"profile"} href={`tel:${v.phone}`}>☎ {decodeDisplayText(v.phone)}</VendorContactLink>}{v.email&&paid&&<VendorContactLink vendorId={v.id} kind="email" source={fromBuilder?"wedding_builder":"profile"} href={`mailto:${v.email}`}>✉ {decodeDisplayText(v.email)}</VendorContactLink>}{v.website&&<VendorContactLink vendorId={v.id} kind="website" source={fromBuilder?"wedding_builder":"profile"} href={safeHref(v.website)} target="_blank" rel="noreferrer">↗ Visit Website</VendorContactLink>}</>}{pro&&social.length>0&&<div className="sidebarSocials">{social.map(([name,url])=><VendorContactLink key={name as string} vendorId={v.id} kind="social" platform={String(name).toLowerCase()} source={fromBuilder?"wedding_builder":"profile"} href={safeHref(String(url))} target="_blank" rel="noreferrer">{name as string}</VendorContactLink>)}</div>}</div>
    {paid&&<div className="builderSaveCard"><span>♡</span><h3>Add to My Planning</h3><p>Save this vendor while you compare your wedding options.</p><FavoriteButton vendorId={v.id} initialFavorite={initialFavorite} loggedIn={!!user} source={fromBuilder?"wedding_builder":"profile"}/></div>}
  </aside></div></section>
 </main>
}
